        let scales = env["MATRIX_SCALE"].map { [$0] } ?? ["1", "1.6"]
        for dark in themes { for scale in scales {
            launch(accepted ? (env["QUESTION_GROUP"] == "accepted-replacements" ? "accepted-replacements" : "accepted-artwork") : corrected ? "corrected-question" : replacements ? "candidate-replacements" : "candidate", selected[0]["id"] as! String, scale: scale, dark: dark)
            var rows = [[String: Any]]()
            for (index, question) in selected.enumerated() {
                let id = question["id"] as! String
                XCTAssertTrue(app.staticTexts["Fixture: " + id].waitForExistence(timeout: 10))
                XCTAssertTrue(app.staticTexts["Exact question images ready"].waitForExistence(timeout: 10))
                XCTAssertFalse(app.staticTexts["Correct answer"].exists)
                let capture = corrected || accepted || ["S5","S6","S7","S11","S12","S13","T1","T2","T6","T8","T22","X8"].contains(String(id.split(separator: "-").last!))
                let captureName = "question-\(id)-\(dark)-\(scale)"
                if capture { record(captureName + "-inline") }
                let radio = app.buttons.containing(.staticText, identifier: "A").firstMatch
                reach(radio); let choiceLabel = radio.label
                let beforePixels = accepted ? (radio.screenshot().image.cgImage!.dataProvider!.data! as Data) : nil
                radio.tap(); XCTAssertTrue(button(choiceLabel).isSelected)
                if accepted {
                    let afterPixels = radio.screenshot().image.cgImage!.dataProvider!.data! as Data
                    XCTAssertNotEqual(beforePixels!, afterPixels, "Pending choice must visibly change: " + id)
                    record(captureName + "-pending")
                }
                var triggers = (question["stem"] as! Bool) ? ["Enlarge question image"] : []
                if question["optionImages"] as! Int > 0 {
                    XCTAssertEqual(question["optionImages"] as! Int, 4)
                    triggers += ["A", "B", "C", "D"].map { "Enlarge option " + $0 + " image" }
                }
                for trigger in triggers {
                    let enlarge = button(trigger); reach(enlarge, up: trigger != "Enlarge question image"); enlarge.tap()
                    XCTAssertTrue(button("Close").waitForExistence(timeout: 10))
                    XCTAssertFalse(app.staticTexts["Correct answer"].exists)
                    button("Zoom in").tap()
                    XCTAssertTrue(app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS %@", "150%")).firstMatch.waitForExistence(timeout: 5))
                    if capture { record(captureName + "-" + trigger + "-zoom") }
                    button("Reset").tap()
                    XCTAssertTrue(app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS %@", "100%")).firstMatch.waitForExistence(timeout: 5))
                    button("Close").tap()
                    XCTAssertTrue(enlarge.waitForExistence(timeout: 5)); XCTAssertTrue(enlarge.isHittable)
                    XCTAssertTrue(button(choiceLabel).isSelected, "Pending option lost: " + id)
                }
                let confirm = button("Confirm answer  >"); reach(confirm); confirm.tap()
                XCTAssertTrue(app.staticTexts["Selection recorded for this unscored verification fixture."].waitForExistence(timeout: 5))
                rows.append(["question_id": id, "revision": question["revision"]!, "dark": dark, "font_scale": scale, "image_zoom_returns": triggers.count, "native_selection_confirm": "passed", "native_pending_pixels_changed": accepted])
                let data = try JSONSerialization.data(withJSONObject: rows, options: [.sortedKeys])
                let attachment = XCTAttachment(data: data, uniformTypeIdentifier: "public.json")
                attachment.name = "question-matrix-\(start)-\(count)-\(dark)-\(scale)-\(index)"
                attachment.lifetime = .keepAlways; add(attachment)
                if index < selected.count - 1 { button("Next fixture").tap() }
            }
        } }
    }

    func testAcceptedProductionPracticeAndReview() throws {
        let url = Bundle(for: NativeRouteTests.self).url(forResource: "accepted-root-fixtures", withExtension: "json")!
        let fixture = try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as! [String: Any]
        let questions = fixture["questions"] as! [[String: Any]]
        XCTAssertEqual(questions.count, 1000)
        for deferred in [false, true] {
            launch("production", scale: "1.6")
            XCTAssertTrue(button("KörkortGo").waitForExistence(timeout: 10))
            let begin = button("Start a practice test  >"); reach(begin); begin.tap()
            let input = app.descendants(matching: .any).matching(NSPredicate(format: "elementType == %d OR elementType == %d", XCUIElement.ElementType.textField.rawValue, XCUIElement.ElementType.textView.rawValue)).firstMatch
            XCTAssertTrue(input.waitForExistence(timeout: 10)); input.tap()
            input.typeText(String(repeating: XCUIKeyboardKey.delete.rawValue, count: 2) + "1\n")
            if deferred { let option = app.buttons.matching(NSPredicate(format: "label BEGINSWITH %@", "At the end of the test")).firstMatch; reach(option); option.tap() }
            let start = button("Start test  >"); reach(start); start.tap()
            XCTAssertTrue(app.staticTexts["Question 1 of 1"].waitForExistence(timeout: 10))
            let labels = Set(app.descendants(matching: .any).allElementsBoundByIndex.map { $0.label })
            let matches = questions.filter { q in
                labels.contains(q["prompt"] as! String) && ((q["stem"] is NSNull) || labels.contains(q["stem"] as! String))
            }
            XCTAssertEqual(matches.count, 1)
            let q = matches[0]; let wrongLabel = q["wrong_label"] as! String
            let wrong = app.buttons.matching(NSPredicate(format: "label == %@ OR label ENDSWITH %@", wrongLabel, "\n" + wrongLabel)).firstMatch
            reach(wrong); let selectedLabel = wrong.label; wrong.tap()
            button("Learning library").tap(); XCTAssertTrue(button("Keep practising").waitForExistence(timeout: 10)); button("Keep practising").tap()
            XCTAssertTrue(button(selectedLabel).isSelected)
            let confirm = button("Confirm answer  >"); reach(confirm); confirm.tap()
            if deferred { XCTAssertFalse(app.staticTexts["Correct answer"].exists) }
            let finish = button("Finish test  >"); reach(finish); finish.tap()
            XCTAssertTrue(app.staticTexts.matching(identifier: "0 / 1").firstMatch.waitForExistence(timeout: 10)); record("production-\(deferred)-results")
            let review = button("Review answers  >"); reach(review); review.tap(); let incorrect = button("Incorrect"); reach(incorrect); incorrect.tap()
            let expand = button("Review all four options ↓"); reach(expand); expand.tap()
            let correct = app.staticTexts["Correct answer"]; reach(correct); record("production-\(deferred)-review")
            let teaching = button(q["lesson"] as! String); reach(teaching); teaching.tap()
            XCTAssertTrue(button("Return to answer review").waitForExistence(timeout: 10)); record("production-\(deferred)-teaching")
            button("Return to answer review").tap()
            let another = button("Take another test  >"); reach(another); another.tap()
            XCTAssertTrue(input.waitForExistence(timeout: 10)); reach(input); record("production-\(deferred)-setup-return"); XCTAssertTrue(input.label == "1" || input.value as? String == "1", "Inactive Compose input exposes retained text as its label; focused editing uses value")
        }
    }

}
